'use client';

import { useRooms } from '@/hooks/useRooms';
import { useSession } from '@/hooks/useSession';
import { useRouter, useParams } from 'next/navigation';

export default function RoomSidebar() {
    const { rooms, loading: roomsLoading, error } = useRooms();
    const { user } = useSession();
    const router = useRouter();
    const params = useParams();
    const currentRoomId = params?.roomId as string;

    const handleCreateRoom = () => {
        router.push('/rooms'); // Navigate to index/create page
    };

    return (
        <aside className="w-72 bg-white border-r border-gray-200 flex flex-col h-full">
            {/* Header */}
            <div className="px-4 py-4 flex items-center justify-between shrink-0">
                <h2 className="font-semibold text-gray-800 flex items-center gap-2">
                    <span className="text-blue-600">#</span> Rooms
                </h2>
                <button
                    onClick={handleCreateRoom}
                    className="w-8 h-8 rounded-full bg-gray-100 text-blue-600 hover:bg-blue-50 transition flex items-center justify-center"
                >
                    +
                </button>
            </div>

            {/* Room List */}
            <div className="flex-1 px-3 space-y-2 overflow-y-auto">
                {roomsLoading && <p className="text-center text-xs text-gray-400 mt-4">Loading rooms...</p>}
                {error && <p className="text-center text-xs text-red-400 mt-4">Error loading rooms</p>}

                {!roomsLoading && rooms.map(room => (
                    <RoomItem
                        key={room.$id}
                        name={room.name}
                        status={room.status}
                        active={room.$id === currentRoomId}
                        onClick={() => router.push(`/room/${room.$id}`)}
                    />
                ))}

                {!roomsLoading && rooms.length === 0 && (
                    <div className="text-center py-8">
                        <p className="text-sm text-gray-500">No public rooms yet.</p>
                    </div>
                )}
            </div>

            {/* User */}
            <div className="border-t border-gray-200 p-4 flex items-center gap-3 shrink-0 bg-gray-50">
                <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 text-xs font-bold">
                    {user?.username ? user.username.charAt(0).toUpperCase() : '?'}
                </div>
                <div className="min-w-0">
                    <p className="text-sm font-medium truncate">{user?.username || 'Guest'}</p>
                    <p className="text-xs text-green-500 flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
                        Online
                    </p>
                </div>
            </div>
        </aside>
    );
}

function RoomItem({
    name,
    status,
    active,
    onClick
}: {
    name: string;
    status: string;
    active?: boolean;
    onClick?: () => void;
}) {
    return (
        <div
            onClick={onClick}
            className={`px-4 py-3 rounded-xl cursor-pointer transition ${active
                ? "bg-blue-600 text-white shadow-md"
                : "hover:bg-gray-100 text-gray-700"
                }`}
        >
            <p className="font-medium truncate"># {name}</p>
            <p className={`text-xs ${active ? "opacity-90" : "opacity-60"}`}>{status}</p>
        </div>
    );
}
